from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, False)
        option.SetFilter(-1000, 1000, timedelta(0), timedelta(days=730))
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_option = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # The consolidator receives only actual minute bars; missing intervals
        # therefore do not create synthetic five-minute bars.
        self.closes.Add(bar.Close)

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (eligible_time and
                self.previous_fast is not None and
                self.previous_slow is not None and
                self.previous_fast <= self.previous_slow and
                fast > slow):
            self.pending_entry_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, slice):
        self._handle_unexpected_spy_position()

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._handle_expiration_guard()
            self._evaluate_exits(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        current_date = self.Time.date()
        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: SPY has no valid current price.")
            return

        calls = [c for c in chain if c.Right == OptionRight.Call]
        valid_expirations = sorted({
            self._contract_expiry_date(contract)
            for contract in calls
            if (self._contract_expiry_date(contract) - current_date).days >= 7
        })

        if not valid_expirations:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            c for c in calls
            if self._contract_expiry_date(c) == selected_expiry
            and c.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        contract = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {selected_expiry}, "
            f"strike {contract.Strike}."
        )

    def _evaluate_exits(self, slice):
        if self.exit_order_id is not None:
            return

        expiration = self._symbol_expiry_date(self.held_option)
        previous_trading_day = self._previous_trading_day(expiration)

        if self.Time.date() == previous_trading_day and self.Time.time() >= time(15, 45):
            self._submit_exit("time stop before expiration")
            return

        if self.entry_price is None:
            return

        midpoint = self._current_option_midpoint(slice, self.held_option)
        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
            self._cancel_other_open_exit_orders()
            self._submit_exit("50% profit target")

    def _handle_expiration_guard(self):
        expiration = self._symbol_expiry_date(self.held_option)
        if self.Time.date() >= expiration:
            self.no_entry_date = self.Time.date()
            self.Debug(f"Expiration guard: liquidating {self.held_option}.")
            if self.exit_order_id is None:
                self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_option, quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_option}.")

    def _cancel_other_open_exit_orders(self):
        if self.held_option is None:
            return

        for ticket in self.Transactions.GetOpenOrderTickets():
            if ticket.Symbol == self.held_option:
                ticket.Cancel("Replacing open exit with profit-target exit.")

    def _current_option_midpoint(self, slice, symbol):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol != symbol:
                continue

            bid = contract.BidPrice
            ask = contract.AskPrice
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0
            return None

        return None

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy_symbol].Invested:
            return

        has_open_spy_order = any(
            ticket.Symbol == self.spy_symbol
            for ticket in self.Transactions.GetOpenOrderTickets()
        )

        if not has_open_spy_order:
            quantity = -self.Portfolio[self.spy_symbol].Quantity
            self.MarketOrder(self.spy_symbol, quantity)
            self.Debug(
                "Unexpected SPY equity position from exercise/assignment; "
                "submitted liquidation order."
            )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_price:.4f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order did not fill: {order_event.Status}.")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.4f}.")
                self.held_option = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def _contract_expiry_date(self, contract):
        return contract.Expiry.date()

    def _symbol_expiry_date(self, symbol):
        expiry = symbol.ID.Date
        return expiry.date() if hasattr(expiry, "date") else expiry

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while not self.Securities[self.spy_symbol].Exchange.DateIsOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate
