from AlgorithmImports import *
from datetime import timedelta, time as datetime_time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-200, 200)
                                     .Expiration(timedelta(days=0), timedelta(days=365))
        )

        # Manual updates ensure the current Slice is available when a bar closes.
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))

        self.closes = RollingWindow[float](21)
        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.no_entry_date = None
        self.spy_liquidation_order_id = None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_risk()
        self._handle_time_stop()

        # Feed only actual SPY minute bars; missing bars are never synthesized.
        if slice.Bars.ContainsKey(self.spy):
            self.five_minute_consolidator.Update(slice.Bars[self.spy])

            # A consolidator event is emitted synchronously by Update.
            # Test the completed five-minute bar using this same current Slice.
            while self.five_minute_consolidator.WorkingData is None:
                break

        self._evaluate_profit_target(slice)

    def OnEndOfTimeStep(self):
        # Intentionally unused.
        pass

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = order_event.FillPrice
                self.held_contract = order_event.Symbol
                self.entry_order_id = None
                self.Debug(
                    f"ENTRY filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"ENTRY not filled: {order_event.Symbol}")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"EXIT filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}"
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_liquidation_order_id = None

    def OnWarmupFinished(self):
        pass

    def _on_five_minute_bar(self, bar, slice):
        self.closes.Add(bar.Close)

        # Need 21 actual bars to calculate current and preceding 20-bar averages.
        if self.closes.Count < 21:
            return

        bar_end = bar.EndTime
        if not (datetime_time(9, 45) <= bar_end.time() <= datetime_time(14, 30)):
            return

        current_fast = sum(self.closes[i] for i in range(0, 5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(0, 20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        if previous_fast <= previous_slow and current_fast > current_slow:
            self._try_enter(slice, bar_end)

    def _try_enter(self, slice, bar_end):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self._has_option_holding() or self.entry_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"ENTRY skipped {bar_end:%Y-%m-%d %H:%M}: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expirations:
            self.Debug(f"ENTRY skipped {bar_end:%Y-%m-%d %H:%M}: no eligible expiry")
            return

        selected_expiry = eligible_expirations[0]
        spot = self.Securities[self.spy].Price
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"ENTRY skipped {bar_end:%Y-%m-%d %H:%M}: no eligible call")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        if ticket.OrderId > 0:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"ENTRY submitted: {selected.Symbol}, "
                f"expiry {selected_expiry}, strike {selected.Strike}"
            )
        else:
            self.Debug(f"ENTRY skipped {bar_end:%Y-%m-%d %H:%M}: market order rejected")

    def _evaluate_profit_target(self, slice):
        if not self._has_option_holding() or self.exit_order_id is not None:
            return

        if self.entry_fill_price is None or not slice.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("profit target")

    def _handle_time_stop(self):
        if not self._has_option_holding() or self.exit_order_id is not None:
            return

        expiry = self.held_contract.ID.Date
        previous_trading_day = self.Securities[
            self.held_contract
        ].Exchange.Hours.GetPreviousTradingDay(expiry)

        if (self.Time.date() == previous_trading_day.date()
                and self.Time.time() >= datetime_time(15, 45)):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_risk(self):
        if not self._has_option_holding():
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if self.exit_order_id is None:
                self._submit_exit("expiration protection")

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy].Invested or self.spy_liquidation_order_id is not None:
            return

        self.Debug("Unexpected SPY position from exercise/assignment; liquidating")
        tickets = self.Liquidate(self.spy)
        if tickets:
            self.spy_liquidation_order_id = tickets[0].OrderId

    def _submit_exit(self, reason):
        if not self._has_option_holding() or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Direction == OrderDirection.Sell:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket.OrderId > 0:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"EXIT submitted ({reason}): {self.held_contract}")

    def _has_option_holding(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity > 0
        )

    def OnSecuritiesChanged(self, changes):
        # Attach the five-minute close handler once; this avoids reliance on
        # automatic subscription ordering and preserves current-Slice selection.
        if not hasattr(self, "_five_minute_handler_attached"):
            self.five_minute_consolidator.DataConsolidated += self._five_minute_handler
            self._five_minute_handler_attached = True

    def _five_minute_handler(self, sender, bar):
        # The current Slice is not provided by the consolidator callback itself.
        # Entry evaluation is delegated through the algorithm's latest Slice.
        if hasattr(self, "_latest_slice"):
            self._on_five_minute_bar(bar, self._latest_slice)

    def OnData(self, slice):
        self._latest_slice = slice

        self._handle_unexpected_spy_position()
